package com.futahua.papers.mobile;
import android.app.*;import android.os.*;import android.provider.DocumentsContract;import org.json.*;import java.io.*;import java.util.*;
public final class PhoneFileInteractionCheck extends Instrumentation {
 private PhonePeerServer peer;private int passed;private JSONArray checks=new JSONArray();
 private String uri(File f)throws Exception{return DocumentsContract.buildDocumentUri("com.android.externalstorage.documents","primary:"+f.getCanonicalPath().substring(Environment.getExternalStorageDirectory().getCanonicalPath().length()+1)).toString();}
 private void check(boolean ok,String text)throws Exception{if(!ok)throw new IOException(text);passed++;checks.put(text);}
 private String change(String op,File f,File dest,String name,boolean succeeds)throws Exception{String id=UUID.randomUUID().toString();JSONObject req=new JSONObject().put("operation","phone-change").put("action",op).put("uri",uri(f)).put("commandId",id);if(dest!=null)req.put("destinationUri",uri(dest));if(name!=null)req.put("newName",name);peer.localFiles(req);long end=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<end){JSONObject job=peer.localFiles(new JSONObject().put("operation","phone-change-status").put("commandId",id));String phase=job.getString("phase");if(Arrays.asList("completed","failed","uncertain").contains(phase)){check(succeeds==phase.equals("completed"),op+" acknowledged "+phase);return id;}Thread.sleep(50);}throw new IOException("Timed out "+op);}
 private void write(File f,String s)throws Exception{try(FileOutputStream out=new FileOutputStream(f)){out.write(s.getBytes("UTF-8"));out.getFD().sync();}}
 private void remove(File f){if(f.isDirectory()){File[] all=f.listFiles();if(all!=null)for(File c:all)remove(c);}f.delete();}
 @Override public void onCreate(Bundle args){start();}
 @Override public void onStart(){Bundle result=new Bundle();int outcome=Activity.RESULT_OK;File base=new File(Environment.getExternalStorageDirectory(),"Download/PapersFileCheck-"+UUID.randomUUID());List<String> recycled=new ArrayList<>();String imageKey=null;android.net.Uri scannedUri=null;
 try{base.mkdirs();peer=new PhonePeerServer(getTargetContext());File a=new File(base,"a"),b=new File(base,"b");change("create-folder",base,null,"a",true);change("create-folder",base,null,"b",true);check(a.isDirectory()&&b.isDirectory(),"folders exist");
 File text=new File(a,"source.txt");write(text,"verified contents");String local="\\\\papers~phone\\primary\\Download\\"+base.getName()+"\\a\\source.txt";String shared=PhoneStorage.outward(local);check(shared.equals("Internal storage\\Download\\"+base.getName()+"\\a\\source.txt"),"phone reference becomes owner storage path");check(PhoneStorage.inward(shared).equals(local),"PC reference returns to navigable phone path");change("rename",text,null,"renamed.txt",true);text=new File(a,"renamed.txt");check(text.isFile()&&!new File(a,"source.txt").exists(),"rename changes real file");
 change("copy",text,b,null,true);check(new String(java.nio.file.Files.readAllBytes(new File(b,"renamed.txt").toPath()),"UTF-8").equals("verified contents"),"copy verified bytes");change("copy",text,b,null,true);check(new File(b,"renamed (2).txt").isFile(),"copy keeps both names");
 change("move",text,b,null,false);check(text.exists(),"conflicting move retains source");File nested=new File(a,"nested");nested.mkdir();write(new File(nested,"child.txt"),"nested");change("copy",a,b,null,true);check(new File(b,"a/nested/child.txt").exists(),"folder copy retains structure");
 change("move",nested,b,null,true);check(!nested.exists()&&new File(b,"nested/child.txt").exists(),"move publishes before removing source");
 String deleted=change("delete",text,null,null,true);recycled.add(deleted);check(!text.exists()&&new File(Environment.getExternalStorageDirectory(),".PapersRecycle/"+deleted+"/renamed.txt").isFile(),"delete keeps recoverable real file");
 JSONObject denied;try{change("create-folder",base,null,"../escaped",true);throw new IOException("traversal accepted");}catch(IOException e){check(e.getMessage().contains("Invalid file name"),"invalid child name refused");}
 File png=new File(base,"clipboard-fixture.png");android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(1024,256,android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xff829c88);try(FileOutputStream output=new FileOutputStream(png)){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,output);}bitmap.recycle();
 imageKey=PhonePeerServer.hash(png.getCanonicalPath().getBytes("UTF-8"));getTargetContext().getSharedPreferences("shared-file-views",0).edit().putString(imageKey,png.getCanonicalPath()).commit();android.net.Uri imageUri=new android.net.Uri.Builder().scheme("content").authority("com.futahua.papers.mobile.files").appendPath("shared").appendPath(imageKey).appendQueryParameter("name",png.getName()).build();
 String image=PhoneClipboard.image(getTargetContext(),imageUri);check(image.startsWith("data:image/png;base64,"),"clipboard image becomes durable inline PNG");byte[] decoded=android.util.Base64.decode(image.substring(image.indexOf(',')+1),android.util.Base64.DEFAULT);android.graphics.Bitmap thumb=android.graphics.BitmapFactory.decodeByteArray(decoded,0,decoded.length);check(thumb.getWidth()<=512&&thumb.getHeight()<=512,"clipboard icon decode is bounded");thumb.recycle();
 try{PhoneClipboard.image(getTargetContext(),imageUri.buildUpon().clearQuery().appendQueryParameter("name","not-image.txt").build());throw new IOException("accepted nonimage");}catch(IOException expected){check(expected.getMessage().contains("Copy an image"),"clipboard nonimage is refused");}
 PhoneUris uris=new PhoneUris(getTargetContext());JSONObject canonical=uris.call(new JSONObject().put("operation","uri-storage-path").put("uri",uri(png)));check(PhoneStorage.file(android.net.Uri.parse(canonical.getString("uri"))).getCanonicalFile().equals(png.getCanonicalFile()),"pill file resolves into canonical Android storage");
 java.util.concurrent.CountDownLatch scanned=new java.util.concurrent.CountDownLatch(1);final android.net.Uri[] mediaResult=new android.net.Uri[1];android.media.MediaScannerConnection.scanFile(getTargetContext(),new String[]{png.getAbsolutePath()},new String[]{"image/png"},(path,value)->{mediaResult[0]=value;scanned.countDown();});if(!scanned.await(15,java.util.concurrent.TimeUnit.SECONDS)||mediaResult[0]==null)throw new IOException("Fixture media indexing failed");scannedUri=mediaResult[0];JSONObject mediaPath=uris.call(new JSONObject().put("operation","uri-storage-path").put("uri",scannedUri.toString()));check(PhoneStorage.file(android.net.Uri.parse(mediaPath.getString("uri"))).getCanonicalFile().equals(png.getCanonicalFile()),"opaque picked media pill resolves to its real file");byte[] originalPng=java.nio.file.Files.readAllBytes(png.toPath());change("move",png,b,null,true);check(!png.exists()&&Arrays.equals(originalPng,java.nio.file.Files.readAllBytes(new File(b,png.getName()).toPath())),"canonical pill move preserves verified bytes in destination");
 result.putString("result",new JSONObject().put("passed",passed).put("checks",checks).toString());
 }catch(Exception e){outcome=Activity.RESULT_CANCELED;result.putString("error",e.toString());result.putInt("passed",passed);}finally{if(scannedUri!=null)try{getTargetContext().getContentResolver().delete(scannedUri,null,null);}catch(Exception ignored){}if(imageKey!=null)getTargetContext().getSharedPreferences("shared-file-views",0).edit().remove(imageKey).commit();remove(base);for(String id:recycled)remove(new File(Environment.getExternalStorageDirectory(),".PapersRecycle/"+id));if(peer!=null)try{peer.close();}catch(Exception ignored){}}
 finish(outcome,result);
 }
}
